package com.supermercado.pos.ui;

import javax.swing.*;import java.util.*;import java.math.*;import com.supermercado.pos.servicio.*;import com.supermercado.pos.dao.*;import com.supermercado.pos.util.*;import com.supermercado.pos.dominio.*;import java.sql.*;
public class PosFrame extends JFrame {private final java.util.List<Operaciones.Linea> lineas=new ArrayList<>();private final JTextArea lista=new JTextArea(14,48);public PosFrame(){super("POS - Ventas");UI.permiso("VENTA_COBRAR");Operaciones.turno();JPanel p=UI.panel();JTextField codigo=UI.campo(p,"Código de barras");JTextField cantidad=UI.campo(p,"Cantidad");cantidad.setText("1");JButton agregar=new JButton("Agregar");JButton cobrar=new JButton("Cobrar");p.add(agregar);p.add(cobrar);agregar.addActionListener(e->UI.accion(this,()->{try(Connection c=Conexion.obtener()){Producto pr=new ProductoDAO().buscarPorCodigo(c,codigo.getText().trim()).orElseThrow(()->new IllegalArgumentException("Producto no encontrado"));lineas.add(new Operaciones.Linea(pr,Integer.parseInt(cantidad.getText())));refrescar();}catch(SQLException ex){throw new IllegalStateException(ex);}}));cobrar.addActionListener(e->UI.accion(this,()->{new PagoDialog(this,lineas,()->{lineas.clear();refrescar();}).setVisible(true);}));add(p,"North");lista.setEditable(false);add(new JScrollPane(lista),"Center");pack();setLocationRelativeTo(null);}private void refrescar(){StringBuilder b=new StringBuilder();BigDecimal total=BigDecimal.ZERO;for(Operaciones.Linea l:lineas){BigDecimal sub=l.precio.multiply(BigDecimal.valueOf(l.cantidad));total=total.add(sub);b.append(l.nombre).append(" x").append(l.cantidad).append(" Q").append(sub).append("\n");}lista.setText(b+"\nTOTAL Q"+total);}}